let family=Family.initial();
let state=family.children[0];
let parentUnlocked=false;
let params=new URLSearchParams(location.search);
let gameMode=params.get('mode')!=='app';
let variant=['A','B','C'].includes(params.get('variant'))?params.get('variant'):'A';
let view=params.get('screen')||'home';
let taskFilter='all',toolsOpen=false,projectionYears=10,projectionContribute=false,hintVisible=true;
const e=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=value=>Money.format(value);
const button=(label,action,attrs='',style='primary')=>`<button class="btn ${style}" data-action="${action}" ${attrs}>${label}</button>`;
const link=(label,action,attrs='')=>`<button class="text-btn" data-action="${action}" ${attrs}>${label}${icon('arrow',14)}</button>`;
const heading=(title,subtitle,aside='')=>`<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div>${aside}</div>`;
const pill=(label,type='soft')=>`<span class="pill ${type}">${label}</span>`;
const fixedRate=()=>`${(state.rateBps/100).toFixed(2)}%`;
const balanceMarkup=(className='big',value=Engine.assets(state))=>`<span class="money ${className}"><span class="currency">¥</span>${money(value)}</span>`;
const statusLabel={available:'可以接下',accepted:'正在进行',submitted:'等待家长检查',confirmed:'等待报酬兑现',paid:'报酬已到账'};
const pendingTasks=()=>state.tasks.filter(t=>['submitted','confirmed'].includes(t.status));
const pendingRequests=()=>state.requests.filter(r=>r.status==='pending');
const percent=value=>Math.max(0,Math.min(100,value));
function taskArt(task){if(task.art==='book')return Art.book();if(task.art==='plant')return Art.tree('sprout');return `<div style="color:${task.art==='breakfast'?'#c2a276':'#8faaa0'}">${icon(task.art==='breakfast'?'sun':'leaf',40)}</div>`;}
function navigation(){
  if(view.startsWith('parent'))return [{id:'parent',label:'家长概览',icon:'home'},{id:'parent-tasks',label:'劳动确认',icon:'task',count:pendingTasks().length},{id:'parent-payouts',label:'领取申请',icon:'wallet',count:pendingRequests().length},{id:'parent-budget',label:'预算与约定',icon:'settings'},{id:'parent-loans',label:'预支与还款',icon:'book'}];
  return [{id:'home',label:'我的小镇',icon:'home'},{id:'tasks',label:'劳动委托',icon:'task'},{id:'market',label:'理财小屋',icon:'leaf'},{id:'wish',label:'我的愿望',icon:'star'},{id:'growth',label:'成长手账',icon:'chart'}];
}
function render(){
  Game.syncOrientation();
  const screens={home:homePage,tasks:tasksPage,market:marketPage,holdings:holdingsPage,wish:wishPage,growth:growthPage,wallet:walletPage,parent:parentPage,'parent-tasks':parentTasksPage,'parent-payouts':parentPayoutsPage,'parent-budget':parentBudgetPage,loans:loansPage,'parent-loans':parentLoansPage};
  if(!screens[view])view='home';
  const nav=navigation();const isParent=view.startsWith('parent');
  document.body.classList.toggle('game-mode',gameMode&&!isParent);
  if(gameMode&&!isParent){const screen=view;view='home';Game.render();if(screen!=='home')Game.openView(screen);return;}
  Game.stop();
  const navMarkup=nav.map(n=>`<button class="nav-item ${(n.id===view||(n.id==='market'&&view==='holdings')||(n.id==='home'&&view==='wallet'))?'active':''}" data-action="go" data-view="${n.id}">${icon(n.icon,20)}<span>${n.label}</span>${n.count?`<span class="dot-count">${n.count}</span>`:''}</button>`).join('');
  document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar"><button class="brand" data-action="go" data-view="home" aria-label="返回小镇"><span class="brand-mark">${icon('leaf',24)}</span><span class="brand-name">钱钱小镇</span></button><div class="brand-caption">让每份努力 慢慢生长</div><nav class="nav-group" aria-label="主要导航">${navMarkup}</nav><div class="sidebar-bottom"><div class="family-card">${Art.mascot(62)}<h4>${e(state.child)}的第一个小金库</h4><p>劳动赚来的，每一分都算数。</p>${link(isParent?'回到孩子的小镇':'看看我们的约定',isParent?'go':'agreement',isParent?'data-view="home"':'')}</div><p class="sidebar-foot">一点一滴 都是长大</p></div></aside><main class="workspace"><header class="topbar"><div class="breadcrumb">${icon(isParent?'parent':'home',15)}<span>${isParent?'家长空间':'我的小镇'}</span><span>/</span><span>${({home:'今天的故事',tasks:'把努力变成收获',market:'让积累继续生长',holdings:'我的持有',wish:'心里装着的小愿望',growth:'一点一点看见长大',wallet:'每一笔都清楚',parent:'一起守护小小成长','parent-tasks':'确认真实劳动','parent-payouts':'兑现我们的承诺','parent-budget':'说好的，就算数',loans:'提前实现，按约偿还','parent-loans':'约定预支与月供'})[view]}</span></div><button class="mobile-brand" data-action="go" data-view="home"><span class="brand-mark">${icon('leaf',19)}</span>钱钱小镇</button><div class="top-actions">${!gameMode&&!isParent?button('进入2.5D小镇','game-mode','','secondary small'):''}<button class="parent-entry" data-action="go" data-view="${isParent?'home':'parent'}">${icon(isParent?'leaf':'parent',16)}${isParent?'孩子视角':'家长空间'}</button><button class="icon-btn notification-button" data-action="notifications" aria-label="查看消息">${icon('bell',18)}${pendingTasks().length||pendingRequests().length?'<span class="notification-dot"></span>':''}</button><button class="avatar" data-action="profiles" aria-label="切换孩子档案">${Art.mascot(37)}</button></div></header>${identityMarkup()}<div class="view-enter">${screens[view]()}</div><p class="demo-date">${icon('clock',12)} 示例日期 ${state.now} · 家庭约定示例利率，收益由家长按约兑现</p></main></div><nav class="mobile-nav" aria-label="底部导航">${nav.map(n=>`<button class="${n.id===view||(n.id==='market'&&view==='holdings')||(n.id==='home'&&view==='wallet')?'active':''}" data-action="go" data-view="${n.id}">${icon(n.icon,21)}<span>${({home:'小镇',tasks:'劳动',market:'理财',wish:'愿望',growth:'成长',parent:'概览','parent-tasks':'劳动确认','parent-payouts':'领取申请','parent-budget':'预算约定','parent-loans':'预支还款'})[n.id]||n.label}</span></button>`).join('')}</nav>`;
  renderControls();
}
function go(next){if(next.startsWith('parent')&&!parentUnlocked)return showAccess('parent',next);if(view.startsWith('parent')&&!next.startsWith('parent'))parentUnlocked=false;view=next;const url=new URL(location.href);url.searchParams.set('screen',next);history.replaceState(null,'',url);render();window.scrollTo({top:0,behavior:'instant'});}
function homePage(){return heading(`下午好，${e(state.child)} ${icon('sun',23)}`,'每一份小小努力，都值得认真收藏。',pill(`${icon('check',12)} 家长按约兑现`))+({A:homeTown,B:homeJourney,C:homeJournal}[variant])();}
function taskTile(t){
  return `<article class="card task-card"><div class="task-art">${taskArt(t)}</div><span class="task-pay">+ ¥${money(t.amount)}</span><h3>${e(t.name)}</h3><p>${e(t.duration)} · ${t.status==='available'?'在生活里动动手':statusLabel[t.status]}</p><div class="between task-footer">${button(t.status==='available'?'我想试试':t.status==='accepted'?'我完成啦':'看看进度','task-detail',`data-id="${t.id}"`,'secondary small')}${icon('arrow',15)}</div></article>`;
}
function balanceCard(){return `<section class="card balance-card"><div class="between"><span class="number-label">我的小小积累</span><button class="icon-btn" data-action="go" data-view="wallet" aria-label="查看我的账本">${icon('arrow',18)}</button></div>${balanceMarkup()}${Engine.debt(state)?`<p class="tiny gold">另有计划待还 ¥${money(Engine.debt(state))}</p>`:''}<div class="balance-stats"><div><label>零钱钱包</label><strong>¥${money(state.wallet)}</strong></div><div><label>正在慢慢长</label><strong>¥${money(Engine.holding(state))}</strong></div></div></section>`;}
function wishCard(){return `<section class="card wish-card">${pill(`${icon('star',11)} 我的愿望`,'purple')}<div class="wish-art">${Art.telescope()}</div><h3>${e(state.goalName||'第一架天文望远镜')}</h3><p class="wish-summary">离小小的星空<br>又近了一点点</p><div class="progress"><span style="width:${percent(Math.max(0,Engine.net(state))/state.goal*100)}%"></span></div><p class="tiny">扣除计划待还后 ¥${money(Math.max(0,Engine.net(state)))} / ¥${money(state.goal)}</p>${link('去看看我的愿望','go','data-view="wish"')}</section>`;}
function homeTown(){
  const tasks=state.tasks.filter(t=>!['paid','confirmed','submitted'].includes(t.status)).slice(0,2);const p=Engine.active(state)[0];
  return `<button class="mobile-wallet-strip" data-action="go" data-view="wallet"><div><span>我的小小积累</span><strong>¥${money(Engine.assets(state))}</strong></div><div class="strip-side"><span>可用零钱</span><b>¥${money(state.wallet)}</b></div>${icon('arrow',18)}</button><div class="home-columns"><div class="home-left"><section class="hero">${Art.town()}<div class="hero-copy">${pill('欢迎回到钱钱小镇')}<h2>把小小努力，<br>存成大大愿望。</h2><p>动动手，攒下第一笔钱。<br>再给它一点时间，看看会发生什么。</p>${button(`接一个生活委托 ${icon('arrow',15)}`,'go','data-view="tasks"','primary')}</div><span class="hero-floating">${icon('sun',13)} 今天也是慢慢长大的一天</span><div class="hero-corner"><span class="dot"></span>不用着急，长大有自己的节奏</div></section><div class="section-head"><h2>今天，动手做点什么？</h2>${link('全部委托','go','data-view="tasks"')}</div><div class="task-grid">${tasks.length?tasks.map(taskTile).join(''):'<div class="empty full">今天的任务都处理好啦，去小屋看看积累吧。</div>'}</div><div class="section-head"><h2>有一份努力，正在慢慢长</h2>${link('我的持有','go','data-view="holdings"')}</div>${p?`<div class="card holding-row"><div class="holding-art">${Art.tree()}</div><div class="grow"><h3>${Products[p.product].name}</h3><small class="muted">还有 ${Math.max(0,Day.difference(state.now,p.end))} 天到期 · 预计收益 ¥${money(p.expected)}</small></div><div class="holding-money">¥${money(p.principal)}</div><svg class="growth-mini" viewBox="0 0 110 45"><path d="M2 40Q22 35 36 31T62 22 86 12 108 3" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></div>`:`<div class="card between"><div><h3>让下一份努力也住进来</h3><p class="small muted mt8">本金和已经结算的收益，都可以继续投入。</p></div>${button('去存一笔','go','data-view="market"','secondary small')}</div>`}</div><aside class="stack home-right">${balanceCard()}${wishCard()}<div class="soft-promise"><span class="promise-icon">${icon('lock',15)}</span><span>说好的收益，由家长按约兑现。<br><span class="tiny">每一次积累，都有家人的支持。</span></span></div></aside></div>`;
}
function homeJourney(){
  return `<section class="journey"><div class="journey-banner">${Art.mascot(93)}<div>${pill('一次次选择，一步步长大','neutral')}<h2 class="mt8">今天的你，准备走到哪一站？</h2><p>不赶路、不打卡。完成一件现实里的小事，就有了新的故事。</p></div></div><div class="journey-balance"><div class="grow"><div class="number-label">旅途里攒下的努力</div>${balanceMarkup('',Engine.assets(state))}</div><div><small class="muted">可以自由安排</small><div class="stat-num">¥${money(state.wallet)}</div></div>${link('翻开账本','go','data-view="wallet"')}</div><div class="journey-track">${[
    {number:'01',title:'劳动驿站',text:'给图书分类、照顾花园。选一件现实里的小事，赚一份自己的报酬。',cta:'挑一件我能做的事',view:'tasks',art:'task'},
    {number:'02',title:'积累小屋',text:`钱包里有 ${money(state.wallet)} 元。可以满足今天的愿望，也可以为以后留下来。`,cta:'安排我的一笔钱',view:'market',art:'leaf'},
    {number:'03',title:'愿望山丘',text:`${e(state.goalName||'第一架天文望远镜')}，正在等你。每一次选择都让它更清楚。`,cta:'看看我的愿望',view:'wish',art:'star'},
    {number:'04',title:'年轮观测站',text:'本金、收益、收益再投入。回头看看，每一份变化从哪里来。',cta:'看看积累的力量',view:'growth',art:'chart'},
  ].map(n=>`<div class="journey-node"><div class="journey-step">${n.number}</div><article class="card"><div class="between"><h3>${n.title}</h3><span style="color:#8ba1ac">${icon(n.art,25)}</span></div><p>${n.text}</p>${button(n.cta,'go',`data-view="${n.view}"`,'secondary small')}</article></div>`).join('')}</div></section>`;
}
function homeJournal(){
  return `<section class="journal"><div class="journal-header"><div><span class="journal-date">${state.now} · ${e(state.child)}的小小记录</span><h2 class="mt8">我的零花钱手账</h2></div>${icon('book',32)}</div><div class="journal-total"><div><div class="number-label">每一分，都有一个故事</div>${balanceMarkup('',Engine.assets(state))}</div><div class="journal-stamp">${icon('check',18)}<br>真实劳动，认真积累<br><span class="tiny">家长按约兑现收益</span></div></div>${[
    {n:'一',title:'今天，我想亲手赚一点',sub:'现实生活中的劳动委托',cta:'找件小事',view:'tasks',icon:'task'},
    {n:'二',title:`零钱钱包里有 ¥${money(state.wallet)}`,sub:'我的钱，可以自己作选择',cta:'安排一下',view:'market',icon:'wallet'},
    {n:'三',title:`有 ¥${money(Engine.holding(state))} 正在计划里`,sub:'到期后，收益可以和本金一起继续存',cta:'看看进展',view:'holdings',icon:'leaf'},
  ].map(n=>`<div class="journal-row"><span class="num">${n.n}</span><span style="color:#9a9b7e">${icon(n.icon,22)}</span><div class="grow"><h3>${n.title}</h3><p>${n.sub}</p></div>${button(n.cta,'go',`data-view="${n.view}"`,'ghost small')}</div>`).join('')}<div class="journal-bottom"><button data-action="go" data-view="wish">${icon('star',24)}<strong class="mt8">写着一个小愿望</strong><small>${e(state.goalName||'第一架天文望远镜')}</small></button><button data-action="go" data-view="growth">${icon('chart',24)}<strong class="mt8">看看时间做的事</strong><small>收益留下，会有什么不同？</small></button></div><p class="tiny muted mt24 center">不用和别人比。这里记着的，是你自己的长大。</p></section>`;
}
function tasksPage(){
  const filters=[['all','全部委托'],['available','可以接下'],['accepted','进行中'],['submitted','等家长确认'],['paid','已收获']];
  const list=state.tasks.filter(t=>taskFilter==='all'||t.status===taskFilter||(taskFilter==='submitted'&&t.status==='confirmed'));
  return heading('动动手，赚自己的第一笔钱','先和家长说好要求，再在现实里完成。',pill('真实生活，真实报酬','gold'))+`<div class="chip-tabs">${filters.map(([id,label])=>`<button class="chip ${taskFilter===id?'active':''}" data-action="task-filter" data-filter="${id}">${label}</button>`).join('')}</div><div class="two-columns"><section class="tasks-list">${list.length?list.map(t=>`<article class="card task-wide"><div class="task-icon">${taskArt(t)}</div><div class="grow"><h3>${e(t.name)}</h3><p>${e(t.detail)}</p><div class="mt8">${pill(statusLabel[t.status],t.status==='paid'?'soft':t.status==='submitted'||t.status==='confirmed'?'gold':'neutral')}</div></div><div><div class="reward">+${money(t.amount)}<small> 元</small></div>${button(t.status==='available'?'我想试试':t.status==='accepted'?'完成后告诉家长':'查看进度','task-detail',`data-id="${t.id}"`,t.status==='paid'?'ghost small':'secondary small')}</div></article>`).join(''):'<div class="empty">这里暂时没有委托。换一个分类看看吧。</div>'}</section><aside class="tip-card">${Art.mascot(90)}<h3>先说好，再动手</h3><p>和家长一起明确：做到什么样算完成？报酬是多少？<br><br>做完后请家长检查，再把报酬记进你的钱包。</p><div class="task-steps"><span>接下委托</span>${icon('arrow',11)}<span>现实完成</span>${icon('arrow',11)}<span>家长确认</span></div><div class="divider"></div><p>整理自己的书包、爱护家里的东西，也可以是共同责任，不一定每件事都需要报酬。</p></aside></div>`;
}
function marketPage(){
  return heading('让努力，继续慢慢长','留下多少、等多久，都由你认真作选择。',link('我的持有','go','data-view="holdings"'))+`<div class="metrics mb16"><div class="card metric-card"><span class="metric-icon">${icon('wallet',23)}</span><div class="number-label">可以安排的零钱</div><div class="stat-num">¥${money(state.wallet)}</div></div><div class="card metric-card"><span class="metric-icon">${icon('leaf',23)}</span><div class="number-label">正在持有</div><div class="stat-num">¥${money(Engine.holding(state))}</div></div><div class="card metric-card"><span class="metric-icon">${icon('gift',23)}</span><div class="number-label">已结算收益</div><div class="stat-num green">+${money(state.bonusEarned)}</div></div></div><div class="onboarding-hint">${icon('info',20)}<span class="grow">这里按真实机制模拟，收益来自家长的事前约定。利率为示例，不是银行报价。</span>${link('看看约定','agreement')}</div><div class="product-grid">${['sprout','annual','dividend'].map(key=>{const p=Products[key];return `<article class="card product-card"><div class="product-art">${Art.tree(key)}</div>${pill(p.tag)}<h3>${p.name}</h3><p class="product-description">${p.subtitle}</p><div class="rate green">${(state.rateBps/100).toFixed(2)}<small>%</small></div><div class="rate-label">${p.type==='income'?'家庭教学收益率 · 非基金报价':'家庭约定年利率 · 本期固定'}</div><div class="product-specs"><span>${p.days} 天到期</span><span>${p.minimum/100} 元起</span><span>${p.type==='income'?'现金分红 / 红利再投':'本息可续存'}</span></div>${button(`了解这份计划 ${icon('arrow',15)}`,'product',`data-product="${key}"`,'secondary full')}</article>`;}).join('')}${['money','index'].map(key=>{const p=Products[key];return `<article class="card product-card" style="background:${key==='money'?'#f0f3ed':'#f0edf5'}"><span class="product-art" style="color:${key==='money'?'#9eaf9d':'#a99bb9'}">${icon(key==='money'?'leaf':'chart',95)}</span>${pill('先认识，再决定','purple')}<h3>${p.name}</h3><p class="product-description">${p.subtitle}</p><div class="rate" style="font-size:25px;margin-top:27px;color:#8c9291">收益会变化</div><div class="rate-label">家庭尚未约定亏损承担方式</div><div class="product-specs"><span>认识产品机制</span><span>不动用真实本金</span></div>${button('去产品课堂看看','product',`data-product="${key}"`,'ghost full')}</article>`;}).join('')}</div>`;
}
function holdingsPage(){
  const active=Engine.active(state);const ended=state.positions.filter(p=>p.status!=='active');
  return heading('给努力一点时间','预计收益到期后结算，之后可以领取，也可以继续投入。',button(`${icon('plus',16)} 存一笔钱`,'go','data-view="market"','secondary small'))+`<div class="two-columns"><section class="stack">${active.length?active.map(p=>{const remain=Math.max(0,Day.difference(state.now,p.end));const progress=percent(Day.difference(p.start,state.now)/p.days*100);return `<article class="card holding-card"><div class="between"><div class="row"><div class="holding-art">${Art.tree(p.product)}</div><div><h3>${Products[p.product].name}</h3><p class="small muted mt8">${p.start} 存入</p></div></div>${pill(`还有 ${remain} 天到期`)}</div><div class="holding-stats"><div><small>持有本金</small><strong>¥${money(p.principal)}</strong></div><div><small>到期预计收益</small><strong class="green">+${money(p.expected)}</strong></div><div><small>本期约定年利率</small><strong>${(p.rateBps/100).toFixed(2)}%</strong></div></div><div><div class="progress green"><span style="width:${progress}%"></span></div><div class="between mt8"><span class="end-date">${Day.label(p.end)}到期，结算后再决定去向</span>${link('查看约定','holding-detail',`data-id="${p.id}"`)}</div>${Products[p.product].type==='income'?`<div class="distribution-row mt16"><span>${p.distribution==='reinvest'?'红利再投 · 本息一起续期':'现金分红 · 收益进零钱'}</span>${link('更改方式','distribution',`data-id="${p.id}"`)}</div>`:''}</div></article>`;}).join(''):`<div class="empty">${icon('leaf',40)}现在没有持有中的计划。<br>你可以从一份适合自己的计划开始。<div class="mt16">${button('去小屋看看','go','data-view="market"','secondary')}</div></div>`}${ended.length?`<section class="card"><h3>已经走过的年轮</h3>${ended.map(p=>`<div class="ledger-item"><span class="ledger-icon">${icon('check',18)}</span><div class="grow"><h4>${Products[p.product].name} · ${p.status==='matured'?'到期结算':'按约提前取回'}</h4><p>原本金 ¥${money(p.principal)} · ${p.renewalId?`已按${p.distribution==='cash'?'现金分红':'红利再投'}续期`:p.renewalMessage||'本金与结算收益已回钱包'}</p></div>${pill('已结束','neutral')}</div>`).join('')}</section>`:''}</section><aside class="tip-card">${Art.tree()}<h3>到期不等于“必须花掉”</h3><p>把本金和已结算的收益一起存入下一期，下一次参与计算的钱就变多了。<br><br>新一期利率和预算，也需要先确认。已经约定的一期不会被临时改掉。</p>${link('看看收益再投入的不同','go','data-view="growth"')}</aside></div>`;
}
function walletPage(){
  return heading('每一笔，都有来处','劳动、收益、投入和领取，清清楚楚记下来。',button('申请领取','withdraw','','secondary small'))+`<div class="metrics mb16"><div class="card metric-card"><div class="number-label">零钱钱包 · 可申请领取</div><div class="stat-num">¥${money(state.wallet)}</div></div><div class="card metric-card"><div class="number-label">持有中的本金</div><div class="stat-num">¥${money(Engine.holding(state))}</div></div><div class="card metric-card"><div class="number-label">等待实际领取</div><div class="stat-num gold">¥${money(Engine.pendingCash(state))}</div></div></div><div class="two-columns"><section class="card"><div class="between"><h3>我的小账本</h3>${pill('每一份努力都记得','neutral')}</div>${ledgerMarkup(state.history)}</section><aside class="stack"><div class="card card-tint"><h3>我的钱从哪里来</h3><div class="rule-row"><span>劳动报酬累计</span><strong>¥${money(state.laborTotal)}</strong></div><div class="rule-row"><span>家长按约结算收益</span><strong>¥${money(state.bonusEarned)}</strong></div><div class="rule-row"><span>已经实际领取</span><strong>−¥${money(state.withdrawn)}</strong></div><div class="rule-row"><span>已用于还款</span><strong>−¥${money(state.repaidTotal)}</strong></div><div class="rule-row"><span>账户资产</span><strong>¥${money(Engine.assets(state))}</strong></div></div>${debtCard()}<p class="note">${icon('info',16)}<span>领取申请中的钱仍然属于你，家长实际交付后才从账户扣除。持有中的本金需按约取回后再领取。</span></p></aside></div>`;
}
function ledgerMarkup(list){return `<div class="ledger-list">${list.slice(0,18).map(h=>`<div class="ledger-item"><span class="ledger-icon">${icon(({income:'task',yield:'leaf',invest:'leaf',request:'clock',withdraw:'wallet',repay:'book','loan-funded':'gift','loan-request':'clock',choice:'settings'})[h.type]||'coin',18)}</span><div class="grow"><h4>${e(h.title)}</h4><p>${h.date} · ${e(h.detail)}</p></div><span class="amount ${['income','yield'].includes(h.type)?'green':''}">${['income','yield'].includes(h.type)?'+':['withdraw','repay'].includes(h.type)?'−':''}${money(h.amount)}</span></div>`).join('')}</div>`;}
